const lessons=[{"sentences":[{"speaker":"A","text":"Hi Mark, do you know when the printed materials for the regional conference will arrive?","position":1,"audioStartSeconds":0,"audioEndSeconds":5.391583333333333},{"speaker":"B","text":"The delivery was actually scheduled for yesterday morning, but the courier service experienced a major truck breakdown.","position":2,"audioStartSeconds":5.591583333333333,"audioEndSeconds":12.813083333333333},{"speaker":"A","text":"That is a huge problem because our marketing presentation starts tomorrow afternoon.","position":3,"audioStartSeconds":13.013083333333332,"audioEndSeconds":18.2845},{"speaker":"B","text":"I called customer support this morning and they promised to dispatch a replacement batch by express shipping today.","position":4,"audioStartSeconds":18.4845,"audioEndSeconds":24.889916666666668},{"speaker":"A","text":"Will those express boxes definitely reach our office before we leave for the convention center?","position":5,"audioStartSeconds":25.089916666666667,"audioEndSeconds":30.644041666666666},{"speaker":"B","text":"They should arrive by noon tomorrow if the courier keeps their promise.","position":6,"audioStartSeconds":30.844041666666666,"audioEndSeconds":35.16104166666667},{"speaker":"A","text":"Great, I will inform the team so everyone stays calm about the delay.","position":7,"audioStartSeconds":35.361041666666665,"audioEndSeconds":40.25791666666667},{"speaker":"A","text":"Good morning Sarah, I need to update the delivery address for our new office furniture order.","role":"section-start","position":8,"audioStartSeconds":45.25791666666667,"audioEndSeconds":50.73475},{"speaker":"B","text":"We already processed the warehouse paperwork for the downtown branch yesterday.","position":9,"audioStartSeconds":50.93475,"audioEndSeconds":55.921875},{"speaker":"A","text":"Our lease negotiations fell through, so we are moving into the suburban building instead.","position":10,"audioStartSeconds":56.121875,"audioEndSeconds":61.79195833333333},{"speaker":"B","text":"That changes everything because the shipping fee for the suburban zone is quite different.","position":11,"audioStartSeconds":61.991958333333336,"audioEndSeconds":67.18525},{"speaker":"A","text":"Can you contact the logistics department before they load the trucks?","position":12,"audioStartSeconds":67.38525,"audioEndSeconds":71.62495833333334},{"speaker":"B","text":"I will send them an urgent message right now and confirm the new location.","position":13,"audioStartSeconds":71.82495833333333,"audioEndSeconds":76.382375},{"speaker":"A","text":"Thank you so much for handling this change so quickly.","position":14,"audioStartSeconds":76.582375,"audioEndSeconds":80.34416666666667}],"questions":[{"prompt":"What event are the speakers discussing in the first conversation?","options":["A regional conference.","A marketing workshop.","A company anniversary."],"answer":"A","evidenceSentence":1,"evidence":"printed materials for the regional conference","explanation":"Người nói nhắc đến tài liệu in cho hội nghị khu vực."},{"prompt":"Why are the conference materials delayed?","options":["The printer made a mistake.","The delivery truck broke down.","The office was closed."],"answer":"B","evidenceSentence":2,"evidence":"courier service experienced a major truck breakdown","explanation":"Dịch vụ chuyển phát gặp sự cố hỏng xe tải lớn."},{"prompt":"When does Speaker B expect the replacement packages to arrive?","options":["By noon tomorrow.","This afternoon.","Next Monday."],"answer":"A","evidenceSentence":6,"evidence":"arrive by noon tomorrow","explanation":"Họ dự kiến nhận được hàng vào khoảng trưa ngày mai."},{"prompt":"What does Speaker A want to update in the second conversation?","options":["The office furniture order.","The delivery address.","The warehouse paperwork."],"answer":"B","evidenceSentence":8,"evidence":"update the delivery address","explanation":"Người nói muốn cập nhật địa chỉ giao hàng."},{"prompt":"Why must the delivery location be changed?","options":["The downtown office is too small.","The lease negotiations failed.","The furniture was damaged."],"answer":"B","evidenceSentence":10,"evidence":"lease negotiations fell through","explanation":"Các cuộc đàm phán thuê mặt bằng không thành công."},{"prompt":"What will Speaker B do next?","options":["Send an urgent message to logistics.","Call the downtown branch manager.","Pay the shipping fee immediately."],"answer":"A","evidenceSentence":13,"evidence":"send them an urgent message right now","explanation":"Người nghe sẽ gửi tin nhắn khẩn cấp cho bộ phận hậu cần."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
